package org.apache.hadoop.http;

import org.eclipse.jetty.server.CustomRequestLog;
import org.eclipse.jetty.server.RequestLog;
import org.eclipse.jetty.server.Slf4jRequestLogWriter;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TestHttpRequestLog {

  @Test
  public void testRequestLog() {
    RequestLog requestLog = HttpRequestLog.getRequestLog("test");
    assertNotNull("RequestLog should not be null", requestLog);
    assertEquals("Class mismatch",
        CustomRequestLog.class, requestLog.getClass());
    CustomRequestLog customRequestLog = (CustomRequestLog) requestLog;
    assertEquals("Format mismatch", CustomRequestLog.EXTENDED_NCSA_FORMAT,
        customRequestLog.getFormatString());
    assertTrue("Writer class mismatch",
        customRequestLog.getWriter() instanceof Slf4jRequestLogWriter);
    assertEquals("Logger name mismatch", "http.requests.test",
        getLoggerName(requestLog));
  }

  @Test
  public void testAliasedRequestLogs() {
    assertEquals("Logger name mismatch", "http.requests.resourcemanager",
        getLoggerName(HttpRequestLog.getRequestLog("cluster")));
    assertEquals("Logger name mismatch", "http.requests.namenode",
        getLoggerName(HttpRequestLog.getRequestLog("hdfs")));
    assertEquals("Logger name mismatch", "http.requests.nodemanager",
        getLoggerName(HttpRequestLog.getRequestLog("node")));
  }

  private static String getLoggerName(RequestLog requestLog) {
    Slf4jRequestLogWriter writer = (Slf4jRequestLogWriter)
        ((CustomRequestLog) requestLog).getWriter();
    return writer.getLoggerName();
  }
}

